package com.opensocket.aievent.core.a2a;
import java.util.*;import java.util.concurrent.ConcurrentHashMap;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Repository;
@Repository @Profile("!prod") @ConditionalOnProperty(prefix="task",name="store",havingValue="MEMORY",matchIfMissing=true) public class InMemoryA2AReconciliationEvidenceRepository implements A2AReconciliationEvidenceRepository {private final Map<String,A2AReconciliationEvidence> values=new ConcurrentHashMap<>();private String k(String t,String e){return t+"|"+e;}public A2AReconciliationEvidence append(A2AReconciliationEvidence v){values.putIfAbsent(k(v.getTenantId(),v.getEventKey()),v);return values.get(k(v.getTenantId(),v.getEventKey()));}public List<A2AReconciliationEvidence> findByCase(String t,String id,int l){return values.values().stream().filter(v->t.equals(v.getTenantId())&&id.equals(v.getCaseId())).limit(l).toList();}public boolean existsEvent(String t,String e){return values.containsKey(k(t,e));}public String mode(){return "MEMORY_APPEND_ONLY";}}
